            JavaScript

    // A linked list node
class Node {
    constructor(x) {
        // Constructor to initialize a new node with data
        this.data = x;
        this.next = null;
    }
}

// Given the head of a list and an int, appends
// a new node at the end and returns the head.
function insertAtEnd(head, x) {
    // Create a new node
    let newNode = new Node(x);

    // If the Linked List is empty, make
    // the new node as the head and return
    if (head === null) {
        return newNode;
    }

    // Store the head reference in a temporary variable
    let last = head;

    // Traverse till the last node
    while (last.next !== null) {
        last = last.next;
    }

    // Change the next pointer of the last node 
    // to point to the new node
    last.next = newNode;

    // Return the head of the list
    return head;
}

